def build():
    source=json.loads((ROOT/'data/cards.json').read_text())
    notes={}
    for line in ROWS.strip().splitlines():
        if not line.strip(): continue
        number,example,note,check=line.split('|')
        number=int(number)
        assert number not in notes
        notes[number]=dict(example=None if example=='-' else example.replace('\\n','\n'),example_note=note,self_check=check)
    assert set(notes)==set(range(1,116))
    for c in source['cards']:
        extra=notes[c['source_number']]
        if not c['example']: c['example']=extra['example']
        assert c['example'] and extra['example_note'] and extra['self_check'],c['id']
        c['example_note']=extra['example_note'];c['self_check']=extra['self_check']
        c['content_status']='examples_added'
    (ROOT/'data/learning_notes.json').write_text(json.dumps(notes,ensure_ascii=False,indent=2)+'\n')
    target=ROOT/'android/app/src/main/assets/cards.json'
    target.write_text(json.dumps(source,ensure_ascii=False,indent=2)+'\n')
    print('Built 115 complete learning cards; original data/cards.json unchanged')
if __name__=='__main__': build()
